<?php
require __DIR__.'/../includes/bootstrap.php';require_permission('categories');$msg='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$slug=trim($_POST['slug']??'');$image=trim($_POST['existing_image']??'');if(!empty($_FILES['image']['name']))$image=upload_store_image('image');$sort=(int)($_POST['sort_order']??0);if(!$name||!preg_match('/^[a-z0-9-]+$/',$slug))throw new RuntimeException('أدخل اسم القسم ورابطاً لاتينياً صحيحاً.');if($id)db()->prepare('UPDATE categories SET name=?,slug=?,image=?,sort_order=? WHERE id=?')->execute([$name,$slug,$image,$sort,$id]);else db()->prepare('INSERT INTO categories(name,slug,image,sort_order) VALUES(?,?,?,?)')->execute([$name,$slug,$image,$sort]);$msg='تم حفظ القسم.';}catch(Throwable $e){$error=$e->getMessage();}}
$cats=db()->query('SELECT * FROM categories ORDER BY sort_order,id')->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>الأقسام</title><link rel="stylesheet" href="../assets/css/store.css"></head><body><main class="inner"><a href="index.php">← لوحة التحكم</a><h1>إدارة الأقسام</h1><?php if($msg):?><p class="notice"><?=h($msg)?></p><?php endif?><?php if($error):?><p class="notice"><?=h($error)?></p><?php endif?><form method="post" enctype="multipart/form-data" class="admin-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>اسم القسم<input name="name" required></label><label>الرابط اللاتيني (slug)<input name="slug" required></label><label>صورة القسم من الهاتف<input type="file" name="image" accept="image/jpeg,image/png,image/webp,image/gif"></label><label>ترتيب العرض<input type="number" name="sort_order" value="0"></label><button class="gold">إضافة قسم</button></form><div class="table-wrap"><table><tr><th>القسم</th><th>الصورة</th><th>Slug</th><th>الترتيب</th></tr><?php foreach($cats as $c):?><tr><td><?=h($c['name'])?></td><td><?php if($c['image']):?><img width="55" height="55" style="object-fit:cover" src="../<?=h($c['image'])?>"><?php endif?></td><td><?=h($c['slug'])?></td><td><?=$c['sort_order']?></td></tr><?php endforeach?></table></div></main></body></html>